arguments.content:
"""Miner3 2029-10-04: Explore interaction-sign decile factor (IS_h = sign20 * sign5 of realization).

Motivation: existing library is dominated by single-series statics (vol, skew, kurt,
momentum). A factor that conditions a short-term reversal/trend signal on the sign of a
longer-horizon return (regime-consistent beta) may add orthogonal cross-asset tilt.
Tests IS variants with lookbacks (slo, shi) in {(20,5),(40,5),(60,5),(20,10)} and
threshold for near-zero sign. Uses realized 1d-return sign versions as robustness check.
"""
import json, os, sys
import numpy as np
import pandas as pd

sys.path.insert(0, "scripts")
from miner2_20260730_factorlib import (
    TRADABLE, load_panel, fwd_ret_panel, ic_series, rank_turnover, validate,
)

P = load_panel().loc[: "2029-10-03"]
print("panel:", P.shape, P.index.min().date(), "->", P.index.max().date())

FR = {h: fwd_ret_panel(P, h) for h in [1, 2, 3, 5, 10, 20]}


def ish_factor(panel, slo, s, tol=0.0):
    out = {}
    for a in panel.columns:
        s_ = panel[a].dropna()
        r_long = (s_ / s_.shift(slo) - 1.0)
        r_short = (s_ / s_.shift(s) - 1.0)
        sign_long = np.sign(r_long)
        if tol > 0:
            sign_long = sign_long.where(r_long.abs() > tol, 0.0)
        out[a] = sign_long * r_short
    return pd.DataFrame(out).sort_index()


def run(slo, s, tol):
    fv = factor(TRADABLE_panel(P) if False else P, slo, s, tol)
    # re-align: factor computed from panel series
    fv = factor_from(P, slo, s, tol)
    res = validate(fv, FR[10], f"IS_{slo}_{s}_t{tol}")
    return fv, res


def factor_from(panel, slo, s, tol=0.0):
    out = {}
    for a in panel.columns:
        s_ = panel[a].dropna()
        r_long = (s_ / s_.shift(slo) - 1.0)
        r_short = (s_ / s_.shift(s) - 1.0)
        sl_ = np.sign(r_long)
        if tol > 0:
            sl_ = sl_.where(r_long.abs() > tol, 0.0)
        out[a] = sl_ * r_short
    return pd.DataFrame(out).sort_index()


def factor_panel(panel, fn):
    out = {}
    for a in panel.columns:
        out[a] = fn(panel[a].dropna())
    return pd.DataFrame(out).sort_index()


results = []
for slo, s in [(1, 5), (5, 5), (40, 5), (60, 5), (20, 10), (5, 10), (120, 10)]:
    for tol in [0.0, 1e-5]:
        try:
            fv = factor_from(P, slo, s, tol)
            fwd10 = FR[10].reindex(fv.index)
            res = validate(fv, fwd10, f"IS_{slo}_{s}_t{tol}")
            res.update({"slo": slo, "s": s, "tol": tol})
            results.append(res)
            print(f"IS_{slo}_{s}_t{tol}: ic={res['ic']} icir={res['icir']} "
                  f"hit={res['ic_hit_ratio']} n={res['n_ic_dates']} "
                  f"cov={res['coverage']} turn={res['turnover_10d_rank']} "
                  f"pass={res['passes']}")
        except Exception as e:
            print(f"IS_{slo}_{s}_t{tol} ERROR {e}")

# decay for best candidate
best = max(results, key=lambda r: (abs(r["ic"] or 0), abs(r["icir"] or 0)))
print("\nBEST:", best["label"])
if best["passes"]:
    fv = factor_from(P, best["slo"], best["s"], best["tol"])
    print("decay:", validate(fv, FR_OR, f"decay")["decay_ic_by_horizon"]
          if False else "skip")

print("\nSUMMARY")
for r in results:
    print(f"{r['label']:16s} ic={r['ic']} icir={r['icir']} hit={r['ic_hit_ratio']} pass={r['passes']}")
